import hmac
import hashlib
import os
import time
import struct
from typing import Optional, Tuple

# Configuration
SECRET_KEY = os.environ.get('APP_SECRET_KEY', os.urandom(32))
TOKEN_LIFETIME = 3600

def _create_token_payload(user_id: str, permissions: list) -> bytes:
    """Create binary token payload with user data."""
    timestamp = struct.pack('>I', int(time.time()))
    user_bytes = user_id.encode('utf-8')[:64].ljust(64, b'\x00')
    perm_byte = sum(1 << i for i, p in enumerate(permissions[:8]))
    return timestamp + user_bytes + struct.pack('B', perm_byte)

def _compute_mac(payload: bytes, key: bytes = None) -> bytes:
    """Compute HMAC-SHA256 for payload."""
    if key is None:
        key = SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode()
    return hmac.new(key, payload, hashlib.sha256).digest()

def _safe_compare(a: bytes, b: bytes) -> bool:
    """Length-independent secure comparison to prevent timing attacks."""
    # Ensure both inputs are bytes
    if not isinstance(a, bytes) or not isinstance(b, bytes):
        return False
    # Pad shorter to match longer to avoid length-based timing leak
    max_len = max(len(a), len(b))
    a_padded = a.ljust(max_len, b'\x00')
    b_padded = b.ljust(max_len, b'\x00')
    result = 0
    for x, y in zip(a_padded, b_padded):
        result |= x ^ y
    return result == 0

def generate_token(user_id: str, permissions: list) -> str:
    """Generate an authenticated token for the user."""
    payload = _create_token_payload(user_id, permissions)
    mac = _compute_mac(payload)
    token_bytes = payload + mac
    return token_bytes.hex()

def verify_token(token_hex: str) -> Optional[dict]:
    """Verify token and return user data if valid."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) < 69:  # 4 + 64 + 1 = 69 minimum payload
        return None

    # Split token into payload and provided MAC
    payload = token_bytes[:69]
    provided_mac = token_bytes[69:]

    # Compute expected MAC
    expected_mac = _compute_mac(payload)

    # Verify MAC using our safe comparison
    if not _safe_compare(expected_mac, provided_mac):
        return None

    # Parse payload
    timestamp = struct.unpack('>I', payload[:4])[0]
    if time.time() - timestamp > TOKEN_LIFETIME:
        return None

    user_id = payload[4:68].rstrip(b'\x00').decode('utf-8', errors='replace')
    perm_byte = payload[68]
    permissions = [i for i in range(8) if perm_byte & (1 << i)]

    return {'user_id': user_id, 'permissions': permissions, 'issued_at': timestamp}

def validate_admin_action(token_hex: str, action: str) -> Tuple[bool, str]:
    """Validate that a token has admin permissions for an action."""
    token_data = verify_token(token_hex)
    if token_data is None:
        return False, "Invalid or expired token"

    # Permission 0 = admin
    if 0 not in token_data['permissions']:
        return False, "Insufficient permissions"

    return True, f"Action '{action}' authorized for {token_data['user_id']}"

# API endpoint simulation
def handle_request(method: str, path: str, headers: dict, body: dict = None) -> dict:
    """Simulate HTTP request handling."""
    if path == '/api/token' and method == 'POST':
        user_id = body.get('user_id', '')
        perms = body.get('permissions', [])
        if not user_id:
            return {'status': 400, 'body': {'error': 'user_id required'}}
        token = generate_token(user_id, perms)
        return {'status': 200, 'body': {'token': token}}

    elif path == '/api/admin/action' and method == 'POST':
        token = headers.get('Authorization', '').replace('Bearer ', '')
        action = body.get('action', '')
        success, message = validate_admin_action(token, action)
        status = 200 if success else 403
        return {'status': status, 'body': {'message': message}}

    return {'status': 404, 'body': {'error': 'Not found'}}
